pub mod xip_ast2700_v1 {
    ///BootMCU memory-mapped SPI flash execute-in-place aperture. This is a data window, not a control register block; SPI controller registers are modeled in spi_ast2700_v1.
    #[derive(Copy, Clone, Eq, PartialEq)]
    pub struct XIP {
        ptr: *mut u8,
    }
    unsafe impl Send for XIP {}
    unsafe impl Sync for XIP {}
    impl XIP {
        #[inline(always)]
        pub const unsafe fn from_ptr(ptr: *mut ()) -> Self {
            Self { ptr: ptr as _ }
        }
        #[inline(always)]
        pub const fn as_ptr(&self) -> *mut () {
            self.ptr as _
        }
        ///SPI flash data word array for the 0x20000000..0x3fffffff BootMCU XIP window.
        #[inline(always)]
        pub const fn WORD(self, n: usize) -> crate::common::Reg<u32, crate::common::RW> {
            assert!(n < 134217728usize);
            unsafe {
                crate::common::Reg::from_ptr(
                    self.ptr.wrapping_add(0x0usize + n * 4usize) as _,
                )
            }
        }
    }
}
